<?php require 'includes/header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){if($_POST['action']==='save'){ $id=(int)($_POST['id']??0);
if($id){$s=$pdo->prepare("UPDATE products SET name=?,sku=?,category=?,buying_price=?,selling_price=?,stock_qty=?,reorder_level=?,unit=? WHERE id=?");$s->execute([$_POST['name'],$_POST['sku'],$_POST['category'],$_POST['buying'],$_POST['selling'],$_POST['stock'],$_POST['reorder'],$_POST['unit'],$id]);}
else{$s=$pdo->prepare("INSERT INTO products(name,sku,category,buying_price,selling_price,stock_qty,reorder_level,unit) VALUES(?,?,?,?,?,?,?,?)");$s->execute([$_POST['name'],$_POST['sku'],$_POST['category'],$_POST['buying'],$_POST['selling'],$_POST['stock'],$_POST['reorder'],$_POST['unit']]);}
header('Location: products.php');exit;}}
$products=$pdo->query("SELECT * FROM products WHERE active=1 ORDER BY name")->fetchAll();
?>
<h1>Stock / Products</h1><div class="panel"><h2>Add Product</h2><form method="post"><input type="hidden" name="action" value="save"><div class="row3"><input name="name" placeholder="Product name" required><input name="sku" placeholder="SKU"><input name="category" placeholder="Category" value="General"></div><div class="row3"><input name="buying" type="number" step="0.01" placeholder="Buying price"><input name="selling" type="number" step="0.01" placeholder="Selling price"><input name="stock" type="number" step="0.01" placeholder="Opening stock"></div><div class="row3"><input name="reorder" type="number" step="0.01" value="5" placeholder="Reorder level"><input name="unit" value="pcs"><button>Save Product</button></div></form></div>
<div class="panel"><h2>Current Stock</h2><table><tr><th>Product</th><th>SKU</th><th>Buy</th><th>Sell</th><th>Stock</th><th>Status</th></tr><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['sku'])?></td><td><?=money($p['buying_price'])?></td><td><?=money($p['selling_price'])?></td><td><?=money($p['stock_qty'])?> <?=e($p['unit'])?></td><td><?=$p['stock_qty']<=$p['reorder_level']?'<span class="low">LOW</span>':'OK'?></td></tr><?php endforeach;?></table></div>
<?php require 'includes/footer.php';?>